window.ScripturaLexicons.BDAG_PART_0306 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-01\" data-source=\"BDAG\" data-search=\"προσκλίνω verbo inclinar-se para, ligar-se a, juntar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκλίνω</td><td>verbo</td><td>inclinar-se para, ligar-se a, juntar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-02\" data-source=\"BDAG\" data-search=\"πρόσκλισις, εως, ἡ substantivo feminino inclinação, parcialidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσκλισις, εως, ἡ</td><td>substantivo feminino</td><td>inclinação, parcialidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-03\" data-source=\"BDAG\" data-search=\"προσκολλάω verbo aderir, dedicar-se fielmente, unir-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκολλάω</td><td>verbo</td><td>aderir, dedicar-se fielmente, unir-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-04\" data-source=\"BDAG\" data-search=\"πρόσκομμα, ατος, τό substantivo neutro tropeço, obstáculo, motivo de ofensa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσκομμα, ατος, τό</td><td>substantivo neutro</td><td>tropeço, obstáculo, motivo de ofensa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-05\" data-source=\"BDAG\" data-search=\"προσκοπή, ῆς, ἡ substantivo feminino ocasião de ofensa ou tropeço BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκοπή, ῆς, ἡ</td><td>substantivo feminino</td><td>ocasião de ofensa ou tropeço</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-06\" data-source=\"BDAG\" data-search=\"προσκόπτω verbo bater contra, tropeçar, ofender-se, ofender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκόπτω</td><td>verbo</td><td>bater contra, tropeçar, ofender-se, ofender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-07\" data-source=\"BDAG\" data-search=\"προσκρούω verbo bater violentamente contra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκρούω</td><td>verbo</td><td>bater violentamente contra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-08\" data-source=\"BDAG\" data-search=\"προσκυλίω verbo rolar até BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκυλίω</td><td>verbo</td><td>rolar até</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-09\" data-source=\"BDAG\" data-search=\"προσκυνέω verbo adorar, prestar homenagem, prostrar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκυνέω</td><td>verbo</td><td>adorar, prestar homenagem, prostrar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-10\" data-source=\"BDAG\" data-search=\"προσκυνητής, οῦ, ὁ substantivo masculino adorador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσκυνητής, οῦ, ὁ</td><td>substantivo masculino</td><td>adorador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-11\" data-source=\"BDAG\" data-search=\"προσλαλέω verbo falar a, falar com, dirigir-se a BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσλαλέω</td><td>verbo</td><td>falar a, falar com, dirigir-se a</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-12\" data-source=\"BDAG\" data-search=\"προσλαμβάνω verbo tomar, acolher, levar consigo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσλαμβάνω</td><td>verbo</td><td>tomar, acolher, levar consigo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-13\" data-source=\"BDAG\" data-search=\"προσλέγω verbo responder, replicar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσλέγω</td><td>verbo</td><td>responder, replicar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-14\" data-source=\"BDAG\" data-search=\"πρόσλημψις/πρόσληψις, εως, ἡ substantivo feminino aceitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσλημψις/πρόσληψις, εως, ἡ</td><td>substantivo feminino</td><td>aceitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-15\" data-source=\"BDAG\" data-search=\"προσμένω verbo permanecer, continuar, perseverar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσμένω</td><td>verbo</td><td>permanecer, continuar, perseverar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-16\" data-source=\"BDAG\" data-search=\"προσομιλέω verbo falar a, conversar com BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσομιλέω</td><td>verbo</td><td>falar a, conversar com</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-17\" data-source=\"BDAG\" data-search=\"προσονομάζω verbo dar nome a, nomear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσονομάζω</td><td>verbo</td><td>dar nome a, nomear</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-18\" data-source=\"BDAG\" data-search=\"προσορμίζω verbo entrar no porto, ancorar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσορμίζω</td><td>verbo</td><td>entrar no porto, ancorar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-19\" data-source=\"BDAG\" data-search=\"προσοφείλω verbo dever ainda, dever adicionalmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσοφείλω</td><td>verbo</td><td>dever ainda, dever adicionalmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0306-20\" data-source=\"BDAG\" data-search=\"προσοχθίζω verbo irar-se, indignar-se, sentir-se provocado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσοχθίζω</td><td>verbo</td><td>irar-se, indignar-se, sentir-se provocado</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0306-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκλίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκλίνω</span> 1.º aor. pass. <span class=\"greek\">προσεκλίθην</span>; mais-que-perf. 3.ª sg. pass. <span class=\"greek\">προσεκέκλιτο</span> 2 Macc 14:24 (Hom. et al.; ins; TestSol 12:3 C; Jos., Ant. 5, 193) ativo ‘fazer apoiar-se contra’; em nossa literatura somente pass. intr. inclinar-se para, visando à associação, ligar-se a, juntar-se a alguém, com dat. de pessoa (cf. artigo seguinte; Sext. Emp., Math. 7, 324; escólio sobre Aristoph., Plut. 1027 <span class=\"greek\">τοῖς</span> <span class=\"greek\">δικαίοις</span> <span class=\"greek\">προσεκλίθη</span>; 2 Macc 14:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:36</a> (v. também <span class=\"greek\">προσκολλάω</span>); 1 Cl 47:4; 63:1.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσκλισις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσκλισις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">προσκλίνω</span>; Polyb. 5, 51, 8; 6, 10, 10; Diod S 3, 27, 2; Diog. L., Prooem. 20 al.) preferência relativamente forte por algo, inclinação, em nossa literatura somente em sentido desfavorável <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρόσκλισιν</span> com espírito de parcialidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:21</a> (v.l., como EpArist 5, <span class=\"greek\">πρόσκλησιν</span> convocação, convite); cf. 1 Cl 21:7. <span class=\"greek\">δίχα</span> <span class=\"greek\">προσκλίσεως</span> <span class=\"greek\">ἀνθρωπίνης</span> livre de partidarismo humano 50:2. <span class=\"greek\">προσκλίσεις</span> <span class=\"greek\">ποιεῖσθαι</span> envolver-se em contendas partidárias 1 Cl 47:3; cf. 4.—DELG s.v. <span class=\"greek\">κλίνω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκολλάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκολλάω</span> fut. <span class=\"greek\">προσκολλήσω</span> Ezk 19:1; aor. opt. 3.ª sg. <span class=\"greek\">προσκολλήσαι</span> Dt 28:21. Pass.: 1.º fut. <span class=\"greek\">προσκολληθήσομαι</span>; aor. 3.ª sg. <span class=\"greek\">προσεκολλήθη</span> LXX; em nossa literatura somente pass., usado intransitivamente com o sentido lit. ‘aderir a’ (Jos., Ant. 7, 12, 4 de uma espada que adere à mão de um guerreiro valoroso com o sangue de seus inimigos mortos), passando metaforicamente às relações humanas: aderir estreitamente a, dedicar-se fielmente a, unir-se, com dat. (Pla., Phd. 82e, Leg. 5, 728b; POxy 1901, 26; Sir 6:34; 13:16; TestBenj 8:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:36</a> v.l. (em lugar de <span class=\"greek\">προσεκλίθη</span>).—Do apego que um marido sente por sua esposa (segundo Gen 2:24) <span class=\"greek\">τῇ</span> <span class=\"greek\">γυναικί</span> (LXX v.l.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:5</a> v.l.; <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γυν</span>. (LXX, texto; Philo, Leg. All. 2, 49) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:31</a> (de uma esposa em relação a seu marido POxy 1901, 26; 41; 43; 63).—DELG s.v. <span class=\"greek\">κόλλα</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσκομμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσκομμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">προσκόπτω</span>; ‘contusão’ como resultado de tropeçar Plut., Mor. 1048c; Athen. 3, 97f; ‘tropeço, ofensa’ LXX; TestReub 4:7)</p><p class=\"entry-text\">① ato de tropeçar, o próprio tropeço</p><p class=\"entry-text\">ⓐ <span class=\"greek\">λίθος</span> <span class=\"greek\">προσκόμματος</span> pedra que faz as pessoas tropeçarem (Sir 31:7 <span class=\"greek\">ξύλον</span> <span class=\"greek\">προσκόμματος</span>; Is 8:14 <span class=\"greek\">λίθου</span> <span class=\"greek\">πρόσκομμα</span>) metaf., de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:32f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:8</a>.</p><p class=\"entry-text\">ⓑ fig. <span class=\"greek\">διὰ</span> <span class=\"greek\">προσκόμματος</span> <span class=\"greek\">ἐσθίειν</span> isto é, ‘comer e tropeçar no processo’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:20</a> (<span class=\"greek\">διά</span> A 3c). Alguns colocariam isto sob 2.</p><p class=\"entry-text\">② ocasião de experimentar dor interior (ofender-se) ou dar um passo em falso, motivo de ofensa, motivo para dar um passo em falso</p><p class=\"entry-text\">ⓐ lit. de coisas contra as quais se pode tropeçar ou que podem fazer perder o equilíbrio: obstáculo, impedimento, de estrada acidentada <span class=\"greek\">ἔχει</span> <span class=\"greek\">ἀνοδίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προσκόμματα</span> <span class=\"greek\">πολλά</span> Hm 6, 1, 3.</p><p class=\"entry-text\">ⓑ fig. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">πρόσκομμα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀδελφῷ</span> dar a um membro ocasião de experimentar dor interior ou ofensa, colocar um obstáculo no caminho de um membro (v. <span class=\"greek\">ἀδελφός</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:13</a> (com <span class=\"greek\">σκάνδαλον</span>). <span class=\"greek\">βλέπετε</span> <span class=\"greek\">μή</span> <span class=\"greek\">πως</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐξουσία</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">πρόσκομμα</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀσθενέσιν</span> cuidai para que vossa liberdade não venha de algum modo a tornar-se impedimento para os fracos ou a fazê-los tropeçar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:9</a>. <span class=\"greek\">σεμνότης</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾗ</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">πρόσκομμά</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">πονηρόν</span> reverência, na qual não há motivo maligno de ofensa Hm 2:4.—JLindblom, Z. Begriff ‘Anstoss’ im NT: Strena Philologica Upsaliensis 1922, 1–6. V. <span class=\"greek\">σκάνδαλον</span>, final.—DELG s.v. <span class=\"greek\">κόπτω</span>. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκοπή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκοπή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">προσκόπτω</span>; Polyb.)=<span class=\"greek\">πρόσκομμα</span> 2b (v. esse artigo) ocasião de ofender-se ou de dar um passo em falso, fig. <span class=\"greek\">διδόναι</span> <span class=\"greek\">προσκοπήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:3</a>. Como indica a oração final subsequente, os cristãos não devem dar aos de fora motivo algum para censurar a mensagem cristã, quer por conduta contrária ao ethos cultural, quer por suposta subversão da moral.—DELG s.v. <span class=\"greek\">κόπτω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκόπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκόπτω</span> fut. 3.ª sg. <span class=\"greek\">προσκόψει</span> LXX; 1.º aor. <span class=\"greek\">προσέκοψα</span> (Aristoph., X. et al.; SIG 985, 41; pap, LXX; En 15:11).</p><p class=\"entry-text\">① fazer bater contra algo, bater contra, trans. <span class=\"greek\">τὶ</span> algo (Aristoph., Vesp. 275 <span class=\"greek\">πρ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">δάκτυλον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σκότῳ</span>) <span class=\"greek\">πρός</span> <span class=\"greek\">τι</span> contra algo <span class=\"greek\">πρὸς</span> <span class=\"greek\">λίθον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πόδα</span> <span class=\"greek\">σου</span> (Ps 90:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:11</a> (imagem figurada em ambos).</p><p class=\"entry-text\">② entrar em contato com algo de maneira contundente ou violenta, bater contra, tropeçar, intr. (do cego Tobit, Tob 11:10; Pr 3:23; Jer 13:16) <span class=\"greek\">ἐάν</span> <span class=\"greek\">τις</span> <span class=\"greek\">περιπατῇ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡμέρᾳ</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">προσκόπτει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:9</a>; cf. v. 10. Dos ventos <span class=\"greek\">προσέκοψαν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span> bateram contra a casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:27</a> (preferido a <span class=\"greek\">προσέπεσαν</span> para o v. 25 por JWilson, ET 57, ’45, 138).</p><p class=\"entry-text\">③ experimentar ou causar ofensa, extensão fig. de 1 e 2</p><p class=\"entry-text\">ⓐ ofender-se com, sentir repugnância por, rejeitar (Polyb. 1, 31, 7; 5, 7, 5; 6, 6, 3 e 6; Diod S 4, 4, 6; 4, 61, 7 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑπερβολὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λύπης</span> <span class=\"greek\">προσκόψαντα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ζῆν</span>=relutante em continuar vivendo por causa de sua dor esmagadora; 17, 30, 4; Epict. 1, 28, 10; 3, 22, 89; M. Ant. 6, 20; 10, 30) <span class=\"greek\">προσέκοψαν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λίθῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προσκόμματος</span> (<span class=\"greek\">προσκομμα</span> 1a; <span class=\"greek\">προσκόπτω</span> no sentido de ‘bater o pé contra uma pedra’ Vi. Aesopi I c. 66) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:32</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:8</a> (cf. também Diod S 15, 6, 3 <span class=\"greek\">προσκόπτειν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ῥηθεῖσι</span>=ofender-se com as palavras). <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:21</a> (sobre <span class=\"greek\">πρ</span>. <span class=\"greek\">ἐν</span> cf. Sir 32:20).</p><p class=\"entry-text\">ⓑ causar ofensa (Polyb. 5, 49, 5; 7, 5, 6; Epict. 4, 11, 33; Sir 31:17) com dat. de pessoa (Posidippus Com., Fgm. 36 K. <span class=\"greek\">προσέκοψε</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀνθρώπῳ</span>; Diod S 6, 7, 6 <span class=\"greek\">Διί</span>; 17, 77, 7 al.; Aesop, Fab. 417b H.//350b Ch.//39b H-H. <span class=\"greek\">πρ</span>. <span class=\"greek\">ἀνθρώποις</span>) <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">προσκόψωμεν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> 1 Cl 21:5.—Bibliografia s.v. <span class=\"greek\">πρόσκομμα</span>, final.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκρούω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκρούω</span> (Pl. et al.; POxy 531, 10 [d.C. II]; LXX; TestGad; TestJob 20:5 v.l.; Jos.) bater contra com força, bater contra <span class=\"greek\">τὶ</span> algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:25</a> v.l. (em lugar de <span class=\"greek\">προσπίπτω</span>); 27 v.l. (em lugar de <span class=\"greek\">προσκόπτω</span>, aparentemente em favor da imagem mais forte transmitida por <span class=\"greek\">κρούω</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκυλίω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκυλίω</span> 1.º aor. <span class=\"greek\">προσεκύλισα</span> (Aristoph., Vesp. 202 al.; Polyaenus 2, 31, 3) rolar (até) <span class=\"greek\">τὶ</span> algo <span class=\"greek\">λίθον</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θύρᾳ</span> uma pedra até a abertura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:60</a>; também <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:53</a> v.l.—DELG s.v. <span class=\"greek\">κυλίνδω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκυνέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκυνέω</span> (<span class=\"greek\">κυνέω</span> ‘beijar’) imperf. <span class=\"greek\">προσεκύνουν</span>; fut. <span class=\"greek\">προσκυνήσω</span>; 1.º aor. <span class=\"greek\">προσεκύνησα</span> (Trag., Hdt.+. Frequentemente empregado para designar o costume de prostrar-se diante de pessoas e beijar-lhes os pés ou a orla de sua veste, o chão etc.; os persas faziam isso na presença de seu rei divinizado, e os gregos diante de uma divindade ou de algo sagrado.) expressar em atitude ou gesto a completa dependência de uma figura de elevada autoridade ou submissão a ela, (prostrar-se e) adorar, prestar homenagem, prostrar-se diante de, reverenciar, acolher respeitosamente, no grego ático e posteriormente (p. ex. Appian, Mithrid. 104 §489), empregado com o acus. (assim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:10</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:8</a> [Dt 6:13 v.l.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:22ab</a>, 23b, 24a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:20</a>.—Gen 37:9; Ex 11:8; Judg 7:15 A; pseudepigr.; Philo; Jos., C. Ap. 1, 239, Ant. 2, 13; 7, 250; Just.; Tat.; Mel., P. 92, 690; Ath.); ao lado dele a koiné emprega o dat. (Phryn. p. 463 Lob.; JWittmann, Sprachl. Untersuchungen zu Cosmas Indicopl., diss. Munich 1913, 16; KWolf, Studien z. Sprache des Malalas II, diss. Munich 1912, 34; GKilpatrick in: Studies and Documents 29, ’67, 154–56; B-D-F §151, 2; Rob. 455; 476f), que a LXX (v. também JosAs; ApcMos 27:33) e nossa literatura preferem (v. também EpArist 135; Jos., Ant. 6, 55; Just., D. 30, 3; 78, 9; 88, 1.—Jos., Ant. 6, 154 <span class=\"greek\">πρ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> imediatamente após <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">πρ</span>.). Essa reverência ou adoração é prestada</p><p class=\"entry-text\">ⓐ a seres humanos, mas por esse ato devem ser reconhecidos como pertencentes a uma esfera sobre-humana (Appian, Mithrid. 104 §489: Pompeu; Galen, Protr. 5 p. 12, 2ff ed. WJohn: Sócrates, Homero, Hipócrates, Platão): a um rei (assim Hdt. et al.; cf. 2 Km 18:28; 24:20; 3 Km 1:16, 53. Sobre a proskynesis nos cultos helenísticos dos soberanos v. LTaylor, JHS 47, 1927, 53ff, The Divinity of the Rom. Emperor ’31, esp. 256–66; contra ela WTarn, Alexander the Great II, ’50, 347–73) <span class=\"greek\">ὁ</span> <span class=\"greek\">δοῦλος</span> <span class=\"greek\">προσεκύνει</span> <span class=\"greek\">αὐτῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:26</a> (de uma escrava para com seu <span class=\"greek\">κύριος</span> PGiss 17, 11f=Mitt-Wilck, I/2, 481; v. Jos., Ant. 2, 11); a Pedro por Cornélio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:25</a> (cf. Apollonius [c. 197 d.C.] em Eus., HE 5, 18, 6).—À igreja de Filadélfia <span class=\"greek\">προσκυνήσουσιν</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:9</a> (sobre <span class=\"greek\">πρ</span>. <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">τινος</span> cf. Ps 21:28; 85:9; Is 66:23; TestAbr B 4 p. 108, 17 [Stone 64, 17]).—A Jesus, a quem se presta homenagem como rei messiânico e auxiliador: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:2</a>, 8, 11.—8:2; 9:18; 14:33; 15:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:38</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:20</a>; GJs 20:4 (codd.); 21:1, 2 (codd.). Um homem possesso de espírito imundo pede-lhe um favor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:6</a>. Adoração escarnecedora por parte dos soldados 15:19 (<span class=\"greek\">στέφανος</span> 1). V. também b<span class=\"greek\">ε</span> abaixo.</p><p class=\"entry-text\">ⓑ a seres transcendentes (Deus: Aeschyl. et al.; X., An. 3, 2, 9; 13; Pla., Rep. 3, 398a; Polyb. 18, 37, 10; Plut., Pomp. 626 [14, 4]; Lucian, Pisc. 21 <span class=\"greek\">τῇ</span> <span class=\"greek\">θεῷ</span>; PGM 4, 649. De várias divindades nas ins [v. OGI II 700a índice VIII; Sb 7911ff]; PFlor 332, 11 <span class=\"greek\">θεούς</span>; LXX; Philo, Gig. 54 <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> al.; Jos., Ant. 6, 154; 20, 164 al.; Theoph. Ant. 1, 11 [p. 82, 3]).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. de divindade em culto monoteísta (cristãos, judeus, samaritanos) <span class=\"greek\">κύριον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> <span class=\"greek\">σου</span> <span class=\"greek\">προσκυνήσεις</span> (Dt 6:13 v.l.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:8</a>. <span class=\"greek\">πρ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:21</a>, 23a; cf. 23b. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> (Jos., Ant. 6, 55; 9, 267; cf. Orig., C. Cels. 5, 11, 38 [com <span class=\"greek\">λατρεύειν</span>]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:4</a> (com <span class=\"greek\">πίπτειν</span>), 10b; 22:9. V. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:6</a> (Dt 32:43 LXX). <span class=\"greek\">τῷ</span> <span class=\"greek\">ζῶντι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:10</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ποιήσαντι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανόν</span> 14:7. <span class=\"greek\">πεσὼν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">προσκυνήσει</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> prostrar-se-á e adorará a Deus (cf. 2 Km 9:6 de homenagem diante de Davi) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:25</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:11</a>; 11:16. <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">σου</span> (v. as refs. de Ps em a acima) 15:4. Uso absoluto (SIG 1173, 2; PTebt 416, 7; LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:20ab</a>, 24ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:27</a>. Empregado com <span class=\"greek\">ἀναβαίνειν</span> (UPZ 62, 33 [161 a.C.] <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἀναβῶ</span> <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">προσκυνῆσαι</span>; Jos., Ant. 20, 164) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:11</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:1</a>. Com <span class=\"greek\">πίπτειν</span> (v. Jos., Ant. 8, 119) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:14</a>. <span class=\"greek\">προσεκύνησεν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἄκρον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ῥάβδου</span> <span class=\"greek\">αὐτοῦ</span> inclinou-se em adoração (ou orou) sobre a extremidade de seu bordão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:21</a> (Gen 47:31).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. de adoração de imagens em culto politeísta (LXX; Ar. 3, 2; Just.; Ath. 15, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀγάλματα</span>) <span class=\"greek\">προσκυνεῖν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">νεκροῖς</span> <span class=\"greek\">θεοῖς</span> 2 Cl 3:1 ou <span class=\"greek\">λίθους</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ξύλα</span> <span class=\"greek\">κτλ</span>. 1:6 (cf. EpArist 135 … <span class=\"greek\">οἷς</span> <span class=\"greek\">πρ</span>.). V. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:43</a>; Dg 2:5. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">προσκυνούμενα</span> as coisas que são adoradas por vós 2:4. Uso absoluto, com <span class=\"greek\">θύειν</span> MPol 12:2.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. ao diabo e a seres satânicos (o adversário escatológico Iren. 5, 28, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:7</a> (sobre <span class=\"greek\">πρ</span>. <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">ἐμοῦ</span> v. <span class=\"greek\">α</span> acima). <span class=\"greek\">τὰ</span> <span class=\"greek\">δαιμόνια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:20</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">δράκοντι</span> 13:4a; <span class=\"greek\">τῷ</span> <span class=\"greek\">θηρίῳ</span> 13:4b. <span class=\"greek\">τὸ</span> <span class=\"greek\">θηρίον</span> vv. 8 (<span class=\"greek\">αὐτόν</span>), 12; 20:4. <span class=\"greek\">τῇ</span> <span class=\"greek\">εἰκόνι</span> (Da 3:5 al.) <span class=\"greek\">τοῦ</span> <span class=\"greek\">θηρίου</span> 13:15; cf. 16:2; 19:20. <span class=\"greek\">τὸ</span> <span class=\"greek\">θηρίον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">εἰκόνα</span> <span class=\"greek\">αὐτοῦ</span> 14:9, 11. V. <span class=\"greek\">θηρίον</span> 1b; também PTouilleux, L’Apocalypse et les cultes de Domitien et de Cybèle ’35.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. a anjos (TestAbr A 3 p. 79, 28 [Stone p. 6]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:8</a>; cf. 19:10a.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. O Senhor ressuscitado é especialmente objeto de adoração: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:9</a>, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:52</a> P75 et al. Igualmente o Cristo exaltado MPol 17:3. V. também a acima, final.—Bibliografia s.v. <span class=\"greek\">προσεύχομαι</span>, final; Bolkestein [<span class=\"greek\">δεισιδαιμονία</span>, final] 23ff; JHorst, Proskynein: Z. Anbetung im Urchristentum nach ihrer religionsgesch. Eigenart ’32; Berthe MMarti, Proskynesis and adorare: Language 12, ’36, 272–82; BReicke, Some Reflections on Worship in the NT: TWManson mem. vol. ’59, 194–209.—B. 1469; Kl. Pauly IV 1189. New Docs 2, 68; 3, 77–78; 4, 61f. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσκυνητής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσκυνητής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">προσκυνέω</span>; pap sírio pré-cristão em OGI 262, 21 [III d.C.. V. Dssm., LO 79f=LAE 99]; pap bizantino) adorador <span class=\"greek\">ἀληθινοὶ</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:23</a>.—DELG s.v. <span class=\"greek\">κυνέω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσλαλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσλαλέω</span> fut. 3.ª sg. <span class=\"greek\">προσλαλήσει</span> Ex 4:16; 1.º aor. <span class=\"greek\">προσελάλησα</span> comunicar-se oralmente com alguém, falar a, falar com, dirigir-se a <span class=\"greek\">τινί</span> (Antiphanes Com. 218, 3 Kock; Heniochus Com. 4, 3; cf. Ex 4:16; Wsd 13:17; Jos., Bell. 1, 444) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:43</a>; IEph 3:1; IMg 1:1; IPol 5:1. Uso absoluto (Theophr., Char. 7, 5; Mel., P. 24, 173; 53, 387; pap) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:20</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσλαμβάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσλαμβάνω</span> 2.º aor. <span class=\"greek\">προσέλαβον</span>; perf. <span class=\"greek\">προσείληφα</span>. Médio: fut. 3.ª sg. <span class=\"greek\">προσλήψεται</span> (Just., D. 140, 1); 2.º aor. <span class=\"greek\">προσελαβόμην</span> (Aeschyl., Hdt.+. Primariamente: ‘tomar além disso, tomar adicionalmente’)</p><p class=\"entry-text\">① tomar algo que satisfaz uma necessidade pessoal, tomar, tomar alimento, ativo (X., Mem. 3, 14, 4 <span class=\"greek\">ἄρτον</span>) com gen. partitivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:34</a> v.l.—Médio: tomar (ingerir), de alimento <span class=\"greek\">μηθέν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:33</a>. Com gen. partitivo <span class=\"greek\">τροφῆς</span> v. 36 (v. Ps.-Clem., Hom. 3, 21).</p><p class=\"entry-text\">② promover os próprios fins, explorar, tirar proveito de, ativo (Demosth. 2, 7 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἄνοιαν</span>) <span class=\"greek\">τὴν</span> <span class=\"greek\">νεωτερικὴν</span> <span class=\"greek\">τάξιν</span> a aparência juvenil (de um bispo) IMg 3:1.</p><p class=\"entry-text\">③ tomar ou conduzir à parte para junto de si, tomar à parte, médio <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:32</a>. Assim provavelmente também Ac 18:26: Priscila e Áquila tomam Apolo à parte para instruí-lo sem interrupções.</p><p class=\"entry-text\">④ oferecer acolhimento, receber em sua casa ou círculo de conhecidos, médio <span class=\"greek\">τινά</span> alguém (2 Macc 10:15), de um cristão que recebe outro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:1</a>; 15:7a. De Deus ou Cristo que aceita um crente (cf. Chariton 8, 2, 13 <span class=\"greek\">θεῶν</span> <span class=\"greek\">προσλαμβανομένων</span>) 14:3; 15:7b; 1 Cl 49:6 (cf. Ps 26:10; 64:5; 72:24).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:2</a>; Phlm 12 v.l.; 17 (PTebt 61a, 2 [II a.C.] <span class=\"greek\">πρ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κατοικίαν</span>; BGU 1141, 37 [14 a.C.] <span class=\"greek\">προσελαβόμην</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐμέ</span>). V. <span class=\"greek\">πρόσλημψις</span>.</p><p class=\"entry-text\">⑤ tomar ou trazer consigo, levar consigo, médio; consigo como companheiro ou auxiliar (PFay 12, 10 [103 a.C.] <span class=\"greek\">πρ</span>. <span class=\"greek\">συνεργὸν</span> <span class=\"greek\">Ἀμμώνιον</span>; PAmh 100, 4; POxy 71 II, 9 <span class=\"greek\">προσελαβόμην</span> <span class=\"greek\">ἐμαυτῇ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">βοήθειαν</span> <span class=\"greek\">Σεκοῦνδον</span>; 2 Macc 8:1; Jos., Ant. 18, 4, C. Ap. 1, 241) <span class=\"greek\">ἄνδρας</span> <span class=\"greek\">τινὰς</span> <span class=\"greek\">πονηρούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:5</a>.—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσλέγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσλέγω</span> (Hom. et al., mas quase sempre na voz média. O ativo é encontrado ocasionalmente nos pap [Mayser 494]) responder, replicar, com dat. de pessoa e seguido de discurso direto introduzido por <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:14</a> v.l. (no Lógion de Freer).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσλημψις/πρόσληψις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσλημψις</span>/<span class=\"greek\">πρόσληψις</span> (a última forma como v.l.; B-D-F §101 s.v. <span class=\"greek\">λαμβάνειν</span>; igualmente Mlt.-H. 247), <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">προσλαμβάνω</span>; Pla.+; PTebt 64b, 6; 72, 246 [II a.C.]; Jos., Ant. 18, 353; Ath., R. 6 p. 54, 5) aceitação no âmbito de uma relação, aceitação (por Deus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:15</a>.—DELG s.v. <span class=\"greek\">λαμβάνω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσμένω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσμένω</span> fut. <span class=\"greek\">προσμενῶ</span> LXX; 1.º aor. <span class=\"greek\">προσέμεινα</span>; perf. inf. <span class=\"greek\">προσμεμενηκέναι</span> (Just., D. 107, 2) (Pind., Hdt.+; ins; UPZ 60, 16 [168 a.C.]; LXX; GrBar 13:3; SibOr 5, 131; Jos., Vi. 62; 63; Just.).</p><p class=\"entry-text\">① manter-se firme na associação, permanecer/ficar com <span class=\"greek\">τινί</span> alguém ou algo</p><p class=\"entry-text\">ⓐ com dat. de pessoa</p><p class=\"entry-text\"><span class=\"greek\">α</span>. lit. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:2</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. sentido figurado <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> permanecer fiel ao Senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:23</a> (Jos., Ant. 14, 20 <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἀριστοβούλῳ</span>).</p><p class=\"entry-text\">ⓑ com dat. de coisa: continuar em <span class=\"greek\">ταῖς</span> <span class=\"greek\">δεήσεσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:5</a>. <span class=\"greek\">τῇ</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:43</a>. <span class=\"greek\">τῇ</span> <span class=\"greek\">προθέσει</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> 11:23 v.l.</p><p class=\"entry-text\">② continuar num lugar além de determinado momento, permanecer mais tempo, prolongar a permanência (Herodas 8, 3) <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἱκανάς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:18</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἐφέσῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:3</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσομιλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσομιλέω</span> 1.º aor. 3.ª sg. <span class=\"greek\">προσωμίλησε</span>(<span class=\"greek\">ν</span>) (Just.); inf. <span class=\"greek\">προσομιλῆσαι</span> (Eur., Thu.+; Just.; Tat. 5, 2; em sentido diferente Ath., R. 5 p. 53, 10) comunicar-se em conversação, falar a, conversar com <span class=\"greek\">τινί</span> alguém (Theognis 1, 31 <span class=\"greek\">κακοῖσι</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">προσομίλει</span> <span class=\"greek\">ἀνδράσιν</span>; Pla., Gorg. 502e; Vett. Val. 353, 1; Philo, Agr. 60; Just., D. 1, 2 al.), de comunicação por carta IEph 9:2.—DELG s.v. <span class=\"greek\">ὅμιλος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσονομάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσονομάζω</span> aor. 3.ª pl. <span class=\"greek\">προσωνόμασαν</span> (Just., A I, 9, 1), inf. <span class=\"greek\">προσονομάσαι</span> 2 Macc 6:2 (desde Hdt. 2, 52; Plut., Alex. 696 [54, 6], Thes. 36, 6; Cass. Dio 57, 5; 59, 4; Diog. L. 2, 85; 3, 50; 7, 135; 147; OGI 56, 22; 24 [III a.C.] <span class=\"greek\">ἣ</span> <span class=\"greek\">προσονομασθήσεται</span> <span class=\"greek\">πέμπτη</span> <span class=\"greek\">φυλή</span>; 90, 39; 2 Macc 6:2; EpArist; Philo, Abr. 57; Just.) dar nome a, nomear; pass. ser nomeado, ser chamado, ave ‘fênix’ 1 Cl 25:2 (Just., D. 61, 1).—DELG s.v. <span class=\"greek\">ὄνομα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσορμίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσορμίζω</span> 1.º aor. pass. <span class=\"greek\">προσωρμίσθην</span> (Hdt. et al.; ins, pap); o ativo, que é raro, significa ‘conduzir um navio ao porto’, o aoristo médio (Philo, Agr. 64, cf. Somn. 2, 143) ou passivo (Arrian, Anab. 6, 4, 6; 20, 7; Aelian, VH 8, 5; Cass. Dio 41, 48; 64, 1), entrar no porto, ancorar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.53\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:53</a>.—DELG s.v. 2 <span class=\"greek\">ὅρμος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσοφείλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσοφείλω</span> (Thu. et al.; ins, pap) dever além disso, dever ainda (POxy 101, 42 e frequentemente nos pap) <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> algo a alguém, de dívidas pendentes (PHib 63, 14 <span class=\"greek\">τὸ</span> <span class=\"greek\">λοιπὸν</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">προσοφείλεις</span> <span class=\"greek\">μοι</span>) <span class=\"greek\">καὶ</span> <span class=\"greek\">σεαυτόν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">προσοφείλεις</span> deves-me até mesmo a ti próprio (além disso) Phlm 19. Embora nem sempre seja possível encontrar alguma força especial na prep. e diferenciar o composto do verbo simples, além da estrutura retórica, a concentração de expressões comerciais na carta aponta para certa ênfase no prefixo.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0306-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσοχθίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσοχθίζω</span> (<span class=\"greek\">ὀχθίζω</span> ‘ficar muito irado’) fut. <span class=\"greek\">προσοχθιῶ</span> LXX; 1.º aor. <span class=\"greek\">προσώχθισα</span> (-<span class=\"greek\">ησα</span> v.l. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:10</a>, 17; JosAs 9 [cod. A p. 50, 1 Bat.]); perf. <span class=\"greek\">προσώχθικα</span> Gen 27:46; aor. 3.ª sg. pass. <span class=\"greek\">προσωχθίσθη</span> 2 Km 1:21 ficar profundamente contrariado por algo que alguém fez, irar-se, sentir-se ofendido, provocado (LXX; TesJud 18:5; SibOr 3, 272) com dat. de pessoa, contra alguém (Cass. Dio 7, 21, 3; TestDan 5:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:17</a>. Com dat. de coisa (SibOr 3, 272) <span class=\"greek\">τῇ</span> <span class=\"greek\">γενεᾷ</span> <span class=\"greek\">ταύτῃ</span> v. 10 (Ps 94:10). Uso absoluto Hs 9, 7, 6.—DELG s.v. <span class=\"greek\">ὀχθέω</span>. M-M.</p></section></article>"};
